public static int duration(String clip){return switch(clip){
case "idle_breath" -> 80;
case "idle_sit" -> 120;
case "sleep_curl_in" -> 34;
case "sleep_curl_loop" -> 100;
case "wake_up" -> 30;
case "stretch_front" -> 46;
case "groom_paw" -> 70;
case "walk" -> 24;
case "turn_attention" -> 22;
case "loaf_rest" -> 36;
case "eat_milk" -> 76;
case "eat_fish" -> 65;
case "pet_rub" -> 28;
case "threat_warn" -> 70;
case "hypnosis_song" -> 40;
case "pounce_kill" -> 30;
case "recover" -> 34;
default -> 80;};}
public static boolean loop(String c){return java.util.Set.of("hypnosis_song","idle_breath","idle_sit","sleep_curl_loop","walk").contains(c);}
